	zip.Describe("POST /v1/todo/projects/:key/issues/:num/claim", zip.Doc{
		Description: "Takes an issue: it becomes yours and it moves to in_progress.\n\nThe holder is the CALLER, never an argument. \"Assign this to someone else\" is\na different act with different authority, and it already exists as a PATCH;\nconflating them would let anyone hand work to anyone by naming them.\n\nClaiming something already held by someone else is refused rather than\nsilently taken — two agents on one issue is the failure this prevents, and a\nclaim that quietly wins a race is worse than one that says no.",
		Fields: map[string]string{
			"issueHit.assignee": "Assignee is who holds the work. EMPTY MEANS UNHELD, which is what makes the\nissue claimable: claiming one already held by someone else is refused with\n409 rather than quietly taken.",
			"issueHit.kind":     "Kind is what the row IS: issue, pr or epic.",
			"issueHit.number":   "Number is the issue's number on that board, from 1 and monotonic there.\nUnique per board, never across the org — so it addresses an issue only\ntogether with Project.",
			"issueHit.priority": "Priority is urgent, high, medium, low or none. Never empty — an unset\npriority is the value \"none\".",
			"issueHit.project":  "Project is the board key the issue is on. It and Number are the issue's\naddress in every other route on this surface, which is why a hit carries it.",
			"issueHit.repo":     "Repo is the git repository the issue is bound to, empty when it is not\nrepo-bound.",
			"issueHit.source":   "Source is which surface opened it: team, git, crm, helpdesk, cms or agent.\n\"git\" is how the mirrored forge and GitHub rows are spelled.",
			"issueHit.status":   "Status is the board column: backlog, todo, in_progress, done or canceled.\nClaiming moves backlog and todo to in_progress and leaves the other three\nwhere they are.",
			"issueHit.title":    "Title is the issue's one-line summary — what the q filter matched, along with\nthe description.",
			"issueHit.url":      "URL is the row's external anchor — its extRef — which is a link only when the\nfeeder sent one. A mirrored GitHub issue carries \"github:owner/repo#123\" and\nan agent's PR row carries the pushed branch. Empty for a row opened here.",
		},
	})
